insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_124'
from (values
('127.871.d.1.A',3,'A student who wants to haul grain for a summer job writes down a goal, the steps and dates, then tracks his hours and reviews the results. He is:','["planning, proposing, conducting and evaluating an occupational experience", "only talking about it", "skipping the plan", "avoiding evaluation"]'::jsonb,0,'A work experience is planned and evaluated.','original'),
('127.871.d.1.A',4,'The final step in managing a supervised occupational experience is to:','["start another job without review", "evaluate the results and decide what to improve", "avoid feedback", "delete the records"]'::jsonb,1,'Evaluation closes the loop.','original'),
('127.871.d.1.B',3,'A student logs the miles driven, fuel purchased and hours worked on his trucking project each day. This shows proper:','["storage skills", "scheduling errors", "record-keeping skills", "guessing skills"]'::jsonb,2,'Accurate records support projects.','original'),
('127.871.d.1.B',4,'Accurate fuel receipts in a trucking project record help the student to:','["skip tracking", "avoid taxes", "hide spending", "calculate cost per mile and prove expenses"]'::jsonb,3,'Records support cost analysis.','original'),
('127.871.d.1.C',3,'A student builds his own spreadsheet with columns for each delivery run''s date, load and mileage. He is using:','["a customized record-keeping system for his experience", "a generic template only", "no system", "a coworker''s lunch list"]'::jsonb,0,'Customized systems fit the project.','original'),
('127.871.d.1.C',4,'A customized record system is most useful when it:','["is never updated", "captures the specific data the project needs", "has no dates", "records unrelated things"]'::jsonb,1,'Fit the system to the need.','original'),
('127.871.d.1.D',3,'A student who leads a youth safety campaign about railroad crossings at his school is taking part in:','["a maintenance repair", "a payroll audit", "a youth leadership opportunity", "a paint project"]'::jsonb,2,'Leadership builds a well-rounded experience.','original'),
('127.871.d.1.D',4,'Serving as an officer in a student transportation club mainly helps a student to:','["avoid responsibility", "reduce teamwork", "skip meetings", "develop leadership, communication and organizational skills"]'::jsonb,3,'Offices build leadership.','original'),
('127.871.d.1.E',3,'A student plans a delivery-van project by listing tasks, a timeline and expected costs of fuel, insurance and tolls. He is developing:','["a work plan and budget", "a floor plan", "a vacation list", "a menu"]'::jsonb,0,'Plans include tasks and costs.','original'),
('127.871.d.1.E',4,'A budget for an occupational experience should compare:','["colors with sizes", "planned costs with expected income", "names with dates", "tools with weather"]'::jsonb,1,'Budgets balance costs and income.','original'),
('127.871.d.2.A',3,'A student learns that in some countries drivers sit on the right and traffic moves on the left, while in the United States it moves on the right. This is a:','["rule for pilots only", "similarity in all nations", "difference between international cultures'' transportation systems", "mistake in a map"]'::jsonb,2,'Cultural differences affect transport.','original'),
('127.871.d.2.A',4,'Both Tokyo and Houston rely on commuter rail, buses and highways. This is:','["a difference in all nations", "a rare exception", "a map error", "a similarity in transportation across different cultures"]'::jsonb,3,'Similar needs lead to similar systems.','original'),
('127.871.d.2.B',3,'A freight company ships electronics to Europe, produce to Asia and machinery to South America. This shows:','["the variety of world markets", "a ban on shipping", "no trade", "a single local market"]'::jsonb,0,'Markets differ around the world.','original'),
('127.871.d.2.B',4,'Exporting goods to a foreign market requires understanding the local:','["team uniforms", "customs, regulations and demand", "weather forecast only", "menu prices"]'::jsonb,1,'Markets differ by rules and demand.','original'),
('127.871.d.2.C',3,'A shipper learns that labels in another country must be in a different language and that cultural holidays affect delivery dates. These are:','["accounting errors", "engine parts", "marketing factors that impact other cultures", "road signs"]'::jsonb,2,'Language and holidays matter.','original'),
('127.871.d.2.C',4,'A company that ignores local customs when advertising a delivery service in a new country may:','["gain every customer", "reduce its costs only", "avoid all risk", "offend customers and lose business"]'::jsonb,3,'Cultural awareness supports marketing.','original'),
('127.871.d.3.A',3,'A new dispatcher learns that ''freight'' means goods being moved and ''logistics'' means planning their movement. She is:','["learning terms associated with the transportation industries", "skipping training", "guessing words", "avoiding vocabulary"]'::jsonb,0,'Know the terms.','original'),
('127.871.d.3.A',4,'In shipping, a ''bill of lading'' is:','["a driver''s lunch order", "a document that lists the cargo and serves as a receipt", "a road sign", "a type of truck engine"]'::jsonb,1,'A bill of lading documents cargo.','original'),
('127.871.d.3.B',3,'Grocery stores stay stocked, workers get to jobs and emergency supplies arrive quickly because of transportation. This shows the:','["small economic role", "lack of any role", "scope and effect of the transportation industry on society", "limited use of trucks"]'::jsonb,2,'Transportation touches everything.','original'),
('127.871.d.3.B',4,'If a major port closed for two weeks, the most likely effect would be:','["no change", "faster delivery", "lower prices everywhere", "delays and shortages in many industries"]'::jsonb,3,'Supply chains depend on ports.','original'),
('127.871.d.3.C',3,'The development of the transcontinental railroad, interstate highways and containerized shipping are examples of:','["significant historical developments in transportation", "unrelated hobbies", "fictional events", "minor changes"]'::jsonb,0,'History shaped transport.','original'),
('127.871.d.3.C',4,'Which current development is changing delivery services today?','["telegraph orders", "use of electric and autonomous vehicles and real-time tracking", "horse-drawn carts", "paper maps only"]'::jsonb,1,'Technology drives change.','original'),
('127.871.d.3.D',3,'Engineers testing drone deliveries and hydrogen-powered trucks are exploring:','["unrelated fields", "old methods", "potential future development of transportation systems", "past events only"]'::jsonb,2,'Prototypes show future directions.','original'),
('127.871.d.3.D',4,'A possible future change that could reduce urban congestion is:','["banning all roads", "increasing parking only", "removing all traffic lights randomly", "wider use of shared autonomous shuttles and improved transit"]'::jsonb,3,'Shared mobility cuts congestion.','original'),
('127.871.d.3.E',3,'A shipping company uses GPS tracking and automated sorting to deliver packages and now ships to buyers in many countries. This shows how:','["emerging technologies and globalization affect transportation", "tracking slows shipping", "technology has no effect", "globalization reduces trade"]'::jsonb,0,'Technology and globalization reshape transport.','original'),
('127.871.d.3.E',4,'Globalization has increased demand for:','["fewer shipments", "container shipping, air cargo and efficient ports", "slower delivery", "local deliveries only"]'::jsonb,1,'Global trade needs freight capacity.','original'),
('127.871.d.3.F',3,'A city debates whether to spend on new bike lanes or road widening, each with trade-offs for safety, cost and traffic. This is comparing:','["only colors", "only weather", "issues affecting transportation such as safety, cost and efficiency", "unrelated topics"]'::jsonb,2,'Compare issues and trade-offs.','original'),
('127.871.d.3.F',4,'A factor that raises costs for trucking companies and that they must weigh is:','["the color of trucks", "school mascots", "lunch menus", "fuel prices and driver shortages"]'::jsonb,3,'Costs and labor affect operations.','original'),
('127.871.d.4.A',3,'A fleet manager sets a budget, schedules drivers, tracks maintenance and supervises staff. These are:','["common business management principles", "random acts", "hobbies", "personal chores"]'::jsonb,0,'Planning, organizing, staffing and controlling.','original'),
('127.871.d.4.A',4,'The management function of controlling means:','["hiring only", "comparing performance to goals and correcting problems", "ignoring results", "setting no goals"]'::jsonb,1,'Controlling monitors results.','original'),
('127.871.d.4.B',3,'A dispatcher takes a leadership workshop and volunteers to mentor new drivers. She is:','["quitting", "avoiding growth", "taking an opportunity for leadership development and personal growth", "ignoring training"]'::jsonb,2,'Training and mentoring build leaders.','original'),
('127.871.d.4.B',4,'Which activity best builds leadership skills in a transportation career?','["avoiding feedback", "working alone silently", "skipping meetings", "leading a safety committee"]'::jsonb,3,'Committees build leadership.','original'),
('127.871.d.4.C',3,'A club president uses an agenda, takes votes and lets each member speak in turn. She is:','["demonstrating democratic principles in running an effective meeting", "ignoring members", "dominating the meeting", "ending debate instantly"]'::jsonb,0,'Order and fairness define a meeting.','original'),
('127.871.d.4.C',4,'In parliamentary procedure, a motion is made, seconded, discussed and then:','["tossed out", "voted on by the members", "ignored", "delayed forever"]'::jsonb,1,'Motions are decided by vote.','original'),
('127.871.d.4.D',3,'A new driver joins a crew that has strong cooperation and trust, and the group finishes loads faster. This describes positive:','["competition only", "misunderstanding", "team dynamics", "isolation"]'::jsonb,2,'Team dynamics are how members work together.','original'),
('127.871.d.4.D',4,'A team that has unclear roles and conflicting goals will most likely experience:','["perfect cooperation", "faster results", "clear expectations", "slow progress and frustration"]'::jsonb,3,'Unclear roles hurt teams.','original'),
('127.871.d.4.E',3,'A regional bus company announces that its mission is to provide safe, reliable and affordable transit and sets a goal of 98 percent on-time arrivals. This is:','["developing organizational vision, mission and goals", "a random slogan", "ignoring customers", "setting no direction"]'::jsonb,0,'Organizations define vision, mission and goals.','original'),
('127.871.d.4.E',4,'A mission statement tells employees:','["the lunch menu", "the organization''s purpose and what it does", "the exact route of one truck", "the weather forecast"]'::jsonb,1,'Mission describes purpose.','original'),
('127.871.d.5.A',3,'A Texas port ships cotton and electronics overseas and receives tires and furniture in return because regions have different resources and strengths. This explains a reason for:','["local-only business", "isolation", "world trade and globalization", "trade bans"]'::jsonb,2,'Countries trade for goods they lack.','original'),
('127.871.d.5.A',4,'Which is a reason nations trade with each other?','["no demand", "lack of ports", "identical products everywhere", "different resources, costs and production strengths"]'::jsonb,3,'Specialization drives trade.','original'),
('127.871.d.5.B',3,'A state debates funding a new highway bypass, with lawmakers, businesses and residents lobbying. This shows the:','["political impact of transportation", "absence of politics", "random events", "no public interest"]'::jsonb,0,'Transportation decisions are political.','original'),
('127.871.d.5.B',4,'Transportation policy often becomes political because:','["laws never change", "funding choices affect jobs, communities and the economy", "roads cost nothing", "nobody uses roads"]'::jsonb,1,'Policy affects many groups.','original'),
('127.871.d.5.C',3,'A trucking company reviews federal hours-of-service rules and updates driver schedules so no driver exceeds the limit. This is:','["ignoring laws", "breaking rules", "reviewing regulations and evaluating their impact on operations", "avoiding paperwork"]'::jsonb,2,'Know and apply regulations.','original'),
('127.871.d.5.C',4,'A major law that shapes safety in trucking is the requirement that drivers:','["carry no records", "drive as long as they want", "skip inspections", "rest between shifts under hours-of-service rules"]'::jsonb,3,'HOS limits fatigue.','original'),
('127.871.d.5.D',3,'A fleet supervisor subscribes to a freight trade journal and reads about new emission rules before they take effect. This shows:','["reading written material to stay current on industry issues", "avoiding research", "skipping reading", "ignoring news"]'::jsonb,0,'Stay informed.','original'),
('127.871.d.5.D',4,'Reading trade publications helps transportation managers to:','["avoid decisions", "anticipate changes in rules, costs and technology", "skip training", "ignore customers"]'::jsonb,1,'Awareness supports planning.','original'),
('127.871.d.5.E',3,'A transit agency surveys riders and counts boardings at each stop before deciding which routes to cut. This is:','["ignoring riders", "guessing", "collecting public opinion and data to make informed decisions", "avoiding data"]'::jsonb,2,'Gather opinion and data.','original'),
('127.871.d.5.E',4,'Which data best supports a decision to add a bus route?','["a rumor", "a single complaint", "the color of the bus", "ridership counts and rider survey results for that area"]'::jsonb,3,'Data supports decisions.','original'),
('127.871.d.5.F',3,'A planner lists three ways to reduce congestion on a bridge, compares their costs and benefits and chooses the best. She is using:','["critical-thinking skills to identify and organize alternatives", "random guessing", "avoiding options", "copying others"]'::jsonb,0,'Compare alternatives.','original'),
('127.871.d.5.F',4,'After listing alternatives for a delivery delay, the next step is to:','["ignore the list", "evaluate each option against cost, time and risk", "pick one at random", "wait for the problem to grow"]'::jsonb,1,'Evaluate before choosing.','original'),
('127.871.d.5.G',3,'A city checks whether a contracted bus operator met the on-time standard in its agreement and reviews safety reports. This is:','["ignoring the contract", "paying without review", "evaluating performance and contract compliance of contractors", "avoiding inspection"]'::jsonb,2,'Contracts require review.','original'),
('127.871.d.5.G',4,'If a contractor repeatedly misses delivery deadlines in the contract, the agency should:','["ignore it", "cancel with no notice", "pay a bonus", "document the problem and enforce the contract terms"]'::jsonb,3,'Enforce agreed terms.','original'),
('127.871.d.6.A',3,'A driver refuses to falsify a logbook even though his dispatcher suggests it, because doing so would be dishonest and illegal. He is examining:','["workplace ethical and legal responsibilities", "dress codes", "pay rates", "personal preferences"]'::jsonb,0,'Ethics and law guide behavior.','original'),
('127.871.d.6.A',4,'Which action best shows ethical responsibility on the job?','["hiding the defect", "reporting a safety defect rather than hiding it", "blaming a coworker", "skipping the report"]'::jsonb,1,'Honesty protects safety.','original'),
('127.871.d.6.B',3,'A new dispatcher greets callers politely, says ''please'' and ''thank you,'' and lets others finish speaking. She is using:','["interruptions", "rude habits", "proper etiquette", "slang only"]'::jsonb,2,'Etiquette shows respect.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_124'
from (values
('127.871.d.6.B',4,'Good business etiquette on a phone call includes:','["answering with a grunt", "talking over the caller", "hanging up abruptly", "identifying yourself and speaking courteously"]'::jsonb,3,'Courtesy builds trust.','original'),
('127.871.d.6.C',3,'A bus driver wears a clean uniform, keeps hair tidy and gets enough rest before a shift. This shows:','["appropriate personal appearance and health habits", "careless dress", "poor grooming", "ignoring rest"]'::jsonb,0,'Appearance and health matter.','original'),
('127.871.d.6.C',4,'Why are healthy habits such as sleep and hydration especially important for professional drivers?','["they reduce paperwork", "they keep reaction time and alertness high", "they shorten routes", "they raise fuel prices"]'::jsonb,1,'Alertness prevents crashes.','original'),
('127.871.d.6.D',3,'An employee writes a clear email to a customer about a delay and then calls a coworker to coordinate a fix. She is practicing:','["silence only", "confusion", "written and oral communication in formal and informal situations", "avoidance"]'::jsonb,2,'Both modes matter.','original'),
('127.871.d.6.D',4,'A formal business letter about a shipment claim should include:','["only a drawing", "jokes and slang", "no details", "the date, the shipment details, a clear request and a polite close"]'::jsonb,3,'Formal writing is complete and polite.','original'),
('127.871.d.6.E',3,'A driver trainee looks at the trainer, nods and repeats the route changes back before leaving. He is practicing:','["effective listening skills", "ignoring directions", "distracted listening", "interrupting"]'::jsonb,0,'Confirm by repeating.','original'),
('127.871.d.6.E',4,'During a safety meeting, effective listening includes:','["texting", "taking notes and asking clarifying questions", "talking over others", "leaving early"]'::jsonb,1,'Listen actively.','original'),
('127.871.d.6.F',3,'A student reads a route map, a bill of lading and a driver''s manual and explains what each requires. He is:','["skipping details", "guessing", "reading and comprehending materials common to transportation", "avoiding documents"]'::jsonb,2,'Understand industry documents.','original'),
('127.871.d.6.F',4,'A freight dispatcher who misreads a delivery address on a manifest could cause:','["faster service", "no effect", "an early arrival", "a misdelivery and added cost"]'::jsonb,3,'Careful reading prevents errors.','original'),
('127.871.d.6.G',3,'Using a manufacturer''s service manual, a student writes step-by-step maintenance instructions for a school bus. He is:','["employing writing and preparation skills with technical information", "guessing", "copying jokes", "doing nothing"]'::jsonb,0,'Technical writing is precise.','original'),
('127.871.d.6.G',4,'Good technical instructions should be:','["random", "clear, ordered and accurate", "vague", "humorous only"]'::jsonb,1,'Instructions must be usable.','original'),
('127.871.d.6.H',3,'A student stands before the class and clearly explains how air brakes work, using visuals and a steady pace. He is demonstrating:','["reading silently", "mumbling", "speaking skills", "silence"]'::jsonb,2,'Present clearly.','original'),
('127.871.d.6.H',4,'One way to strengthen a presentation is to:','["speak very fast", "skip an outline", "read without looking up", "practice ahead of time and make eye contact with the audience"]'::jsonb,3,'Practice improves delivery.','original'),
('127.871.d.7.A',3,'A company explores new engine designs, route-optimization software and battery chemistries. These are:','["major fields of research and development", "decorations", "unrelated hobbies", "payroll tasks"]'::jsonb,0,'R&D covers many fields.','original'),
('127.871.d.7.A',4,'Research and development in transportation often focuses on:','["reducing training", "improving safety, efficiency and fuel use", "adding delays", "lowering quality"]'::jsonb,1,'R&D improves systems.','original'),
('127.871.d.7.B',3,'A team forms a question about tire wear, tests two tire types on a test route and records the results. They are:','["guessing", "copying", "applying scientific methods of research", "ignoring data"]'::jsonb,2,'Question, test, analyze.','original'),
('127.871.d.7.B',4,'For a fair test of two brake pads, the team should:','["change everything at once", "test only once", "skip measuring", "change only one variable and keep the rest the same"]'::jsonb,3,'Control variables.','original'),
('127.871.d.7.C',3,'A student researching a new traffic signal system uses a state DOT report, a university study and an interview with an engineer. She is using:','["a variety of resources for research and development", "one source only", "no sources", "guesses"]'::jsonb,0,'Use several sources.','original'),
('127.871.d.7.C',4,'Which source is likely the most reliable for road safety statistics?','["an anonymous poster", "a government transportation agency report", "a stranger''s comment", "a rumor"]'::jsonb,1,'Official data is reliable.','original'),
('127.871.d.7.D',3,'A researcher states a hypothesis about fuel efficiency, collects data under controlled conditions, analyzes it and draws a conclusion. This describes:','["a guess", "a rumor", "the scientific method of research", "a sales pitch"]'::jsonb,2,'Hypothesis, test, conclusion.','original'),
('127.871.d.7.D',4,'A hypothesis in a transportation experiment is:','["a random opinion", "a final conclusion", "a proven fact", "a testable prediction about the outcome"]'::jsonb,3,'Hypotheses are testable.','original'),
('127.871.d.8.A',3,'A student presents a plan to install better lighting at a bus depot, explaining the goal, cost and expected safety benefit to the manager. They are:','["discussing a project proposal", "making no plan", "avoiding ideas", "ignoring cost"]'::jsonb,0,'Proposals explain goal, cost and benefit.','original'),
('127.871.d.8.A',4,'A strong project proposal for a transportation improvement should include:','["only a drawing", "the problem, the proposed solution, the cost and the expected benefit", "only a slogan", "only a title"]'::jsonb,1,'Proposals are complete.','original'),
('127.871.d.8.B',3,'A transportation technician logs each vehicle''s inspection date, defects found and repairs made. This is:','["losing data", "skipping reports", "maintaining records appropriate to transportation systems", "avoiding paperwork"]'::jsonb,2,'Inspection logs are required records.','original'),
('127.871.d.8.B',4,'Why must a fleet keep accurate maintenance records?','["to avoid inspection", "to hide repairs", "to reduce training", "to show compliance with regulations and track vehicle history"]'::jsonb,3,'Records prove compliance.','original'),
('127.871.d.8.C',3,'A planner records the number of vehicles passing an intersection each hour in a table and plots the counts on a bar graph. She is:','["collecting and organizing data in tables and graphs", "hiding counts", "guessing numbers", "avoiding data"]'::jsonb,0,'Tables and graphs organize data.','original'),
('127.871.d.8.C',4,'Which display best shows how a bus route''s ridership changes over a week?','["a pie chart of unrelated items", "a line graph with days on the horizontal axis", "a map only", "a blank grid"]'::jsonb,1,'Line graphs show change over time.','original'),
('127.871.d.8.D',3,'A chart shows accidents drop sharply after a new speed limit sign was installed. An analyst concludes that:','["nothing changed", "signs always cause crashes", "the sign may have contributed to fewer accidents, and further data should confirm it", "data is useless"]'::jsonb,2,'Interpret trends with caution.','original'),
('127.871.d.8.D',4,'A table shows delivery times of 30, 32, 31, 90 and 29 minutes. The 90-minute time is best described as:','["an error to ignore always", "the typical time", "the average", "an outlier worth investigating"]'::jsonb,3,'Outliers need review.','original'),
('127.871.d.9.A',3,'A dispatcher uses fleet management software to assign routes, emails drivers updates and checks a traffic website. These are:','["management, email and Internet applications used in transportation", "unrelated tools", "hand tools", "office furniture"]'::jsonb,0,'Software supports operations.','original'),
('127.871.d.9.A',4,'Route-planning software helps a delivery company to:','["increase delays", "reduce miles driven and delivery times", "raise costs", "avoid customers"]'::jsonb,1,'Software optimizes routes.','original'),
('127.871.d.9.B',3,'An analyst writes a report, tracks shipments in a spreadsheet, stores customer data in a database and builds slides for a meeting. She is using:','["only a calculator", "no software", "word-processing, database, spreadsheet and presentation software", "only paper"]'::jsonb,2,'Office software types.','original'),
('127.871.d.9.B',4,'Which software is best for calculating the total cost of fuel across a fleet?','["an email program", "a photo editor", "a slide show", "a spreadsheet"]'::jsonb,3,'Spreadsheets calculate.','original'),
('127.871.d.9.C',3,'A logistics team meets over a video call and edits a shared route plan at the same time from different cities. These tools are:','["collaborative, groupware and virtual meeting software", "paper tools", "isolated tools", "hand tools"]'::jsonb,0,'Collaboration software connects teams.','original'),
('127.871.d.9.C',4,'A benefit of virtual meeting software for a national shipping firm is that it:','["slows communication", "allows teams in different places to confer without traveling", "blocks sharing", "requires travel"]'::jsonb,1,'Reduces travel.','original'),
('127.871.d.9.D',3,'A map layer shows delivery stops, a satellite system finds the truck''s exact location and a tracker follows cargo in transit. These are:','["weather vanes", "paper maps only", "GIS, GPS and tracking technologies", "manual guesses"]'::jsonb,2,'Geospatial technologies.','original'),
('127.871.d.9.D',4,'A GPS device determines a vehicle''s position by:','["guessing", "asking nearby drivers", "reading road signs", "using signals from satellites"]'::jsonb,3,'GPS relies on satellites.','original'),
('127.871.d.10.A',3,'Before loading a trailer, a worker wears gloves, lifts with his legs and knows the exit routes in case of fire. He is following:','["safe work practices and emergency procedures", "random steps", "unsafe habits", "no plan"]'::jsonb,0,'Know safe practices and the plan.','original'),
('127.871.d.10.A',4,'If a fuel spill occurs at a depot, the first step in most emergency procedures is to:','["walk through it", "alert others and keep people away from the area", "light a flame", "ignore it"]'::jsonb,1,'Protect people first.','original'),
('127.871.d.10.B',3,'Rules such as OSHA standards and FMCSA regulations are designed to:','["reduce training", "avoid inspections", "promote safety and health in transportation work", "increase accidents"]'::jsonb,2,'Rules protect workers.','original'),
('127.871.d.10.B',4,'An agency that regulates the safety of commercial motor carriers on U.S. roads is the:','["Library of Congress", "Postal Service", "National Park Service", "Federal Motor Carrier Safety Administration"]'::jsonb,3,'FMCSA regulates motor carriers.','original'),
('127.871.d.10.C',3,'A trainee practices chest compressions on a mannequin and applies a pressure bandage. He is demonstrating:','["first aid and CPR procedures", "parking", "cleaning", "office tasks"]'::jsonb,0,'Emergency response skills.','original'),
('127.871.d.10.C',4,'For an adult in sudden cardiac arrest, one key CPR step is to:','["give water", "call 911 and begin chest compressions", "leave the person", "wait for a coworker''s opinion"]'::jsonb,1,'Call and compress.','original'),
('127.871.d.10.D',3,'Before entering the loading dock, a worker puts on a hard hat, high-visibility vest and steel-toe boots. She is demonstrating:','["ignoring rules", "unsafe dress", "proper use of safety equipment", "fashion choices"]'::jsonb,2,'Wear required PPE.','original'),
('127.871.d.10.D',4,'A high-visibility vest helps a ramp worker by:','["adding warmth only", "making work slower", "blocking sound", "making the worker easy for drivers to see"]'::jsonb,3,'Visibility prevents struck-by accidents.','original'),
('127.871.d.10.E',3,'A safety committee walks a warehouse yard, notes blocked exits and cracked pavement and updates the site safety plan. This is:','["evaluating worksite safety areas and plans", "painting a sign", "avoiding inspection", "ignoring problems"]'::jsonb,0,'Walkthroughs find hazards.','original'),
('127.871.d.10.E',4,'After an evaluation of a worksite finds a blocked exit, the safety team should:','["hide it", "correct the hazard and update the plan", "wait a year", "ignore it"]'::jsonb,1,'Fix hazards promptly.','original'),
('127.871.d.11.A',3,'A student studies the age, medical, knowledge-test and skills-test requirements for getting a commercial driver license. He is discussing:','["rules for a bike license", "no rules", "rules for obtaining a CDL", "rules for a boat license only"]'::jsonb,2,'CDL requires tests and eligibility.','original'),
('127.871.d.11.A',4,'Before a skills test for a CDL, most applicants must first obtain a:','["fishing license", "boat permit", "parking pass", "commercial learner''s permit"]'::jsonb,3,'CLP comes before the skills test.','original'),
('127.871.d.11.B',3,'A license that lets a driver operate a tractor-trailer combination with a gross weight of 26,001 pounds or more is a:','["Class A CDL", "learner''s permit only", "bicycle permit", "Class C regular license"]'::jsonb,0,'Class A covers combination vehicles.','original'),
('127.871.d.11.B',4,'A single heavy straight truck over 26,001 pounds, such as a large dump truck, generally requires a:','["moped permit", "Class B CDL", "regular license", "Class A CDL"]'::jsonb,1,'Class B covers single heavy vehicles.','original'),
('127.871.d.11.C',3,'A driver who wants to haul tank trailers carrying liquids adds a special endorsement to his CDL. He is choosing from:','["no options", "only one option", "the various endorsements available for a CDL", "unrelated documents"]'::jsonb,2,'Endorsements add privileges.','original'),
('127.871.d.11.C',4,'A school bus driver must add which endorsement to the CDL?','["H, for hazardous materials", "N, for tank", "T, for double trailers", "S, for school bus"]'::jsonb,3,'S is for school bus.','original'),
('127.871.d.11.D',3,'To earn a hazardous materials endorsement, a driver must pass a knowledge test and a:','["security threat assessment", "typing test", "swimming test", "music test"]'::jsonb,0,'HazMat requires a background check.','original'),
('127.871.d.11.D',4,'Which requirement applies to the passenger endorsement?','["no tests at all", "passing a knowledge test and a skills test in a passenger vehicle", "a tank test only", "a swimming test"]'::jsonb,1,'P endorsement includes testing.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_124'
from (values
('127.871.d.11.E',3,'A warehouse worker operates a sit-down counterbalance forklift to unload pallets, while another uses a pallet jack and a conveyor system. These are:','["hand tools only", "sports gear", "material handling and storage equipment", "office furniture"]'::jsonb,2,'Material handling equipment moves goods.','original'),
('127.871.d.11.E',4,'Before operating a forklift, an operator should:','["skip inspection", "remove the seat belt", "drive with a load raised high", "complete a pre-use inspection and have training and authorization"]'::jsonb,3,'Inspect and be trained.','original'),
